def mod(s,idx,bits):
 layers=['']+s.split(';')
 if idx>=len(layers): return bits
 s=layers[idx]; mods={}
 while s:
  l,m=s[0],s[1];s=s[2:];mods[l]=int(m)
 return {k:min(v+mods.get(k,0),8) for k,v in bits.items()}
